I used the abseil-cpp library using this command:
```
find_package(unofficial-abseil REQUIRED)
target_link_libraries(tao PRIVATE
    unofficial::abseil::algorithm
    unofficial::abseil::base
    unofficial::abseil::container
    unofficial::abseil::debugging
    unofficial::abseil::strings
)
```

The program:
```
#include <iostream>
#include <string>
#include <vector>
#include "absl/strings/str_join.h"

int main() {
    std::vector<std::string> v = {"foo", "bar", "baz"};
    std::string s = absl::StrJoin(v, "-");

    std::cout << "Joined string: " << s << "\n";

    return(0);
}
```

